        {
          "title": "2. 數線三要素與大小比較",
          "content": "畫出一條數線必須具備三個要素：<strong>① 原點 (0)</strong>、<strong>② 正向（箭頭向右）</strong>、<strong>③ 單位長</strong>。在數線上，越右邊的數越大，越左邊的數越小（例如：<code>-2 > -5</code>）。"
        },
        {
          "title": "3. 相反數與絕對值",
          "content": "• <strong>相反數</strong>：在數線上位於原點兩側，且與原點距離相等的兩個數互為相反數（例如 <code>-3</code> 的相反數是 <code>3</code>，<code>0</code> 的相反數是 <code>0</code>）。<br>• <strong>絕對值 <code>|a|</code></strong>：一個數 <code>a</code> 在數線上對應點到原點的距離，距離必大於或等於 0。例如 <code>|-8| = 8</code>。若 <code>|b| = 8</code>，則 <code>b = 8 或 -8</code>。"
        }
