        "steps": [
          "求距離：|(-7) - 5| = |-12| = 12（或直接用右邊大數減左邊小數：5 - (-7) = 5 + 7 = 12）。",
          "求中點坐標：將兩點坐標相加除以 2，即 ((-7) + 5) ÷ 2。",
          "計算 (-2) ÷ 2 = -1，因此中點 C 的坐標為 -1。"
        ]
