          "content": "• <strong>決勝 24 點</strong>：利用卡片上的 4 個數字與 <code>＋、－、×、÷、( )</code> 湊出 24。例如 <code>2, 3, 4, 5</code> 可算 <code>(5 + 3 - 2) × 4 = 24</code>；而 <code>3, 3, 7, 7</code> 善用分數除法：<code>(3 + 3 ÷ 7) × 7 = (24/7) × 7 = 24</code>！<br>• <strong>乘以 11 的速算法原理</strong>：利用分配律 <code>abc × 11 = abc × (10 + 1) = abc0 + abc</code>（頭尾保留、中間兩兩相加，滿十進位）。例如 <code>529 × 11 = 5819</code>。<br>• <strong>乘以 101 的速算法</strong>：<code>34 × 101 = 34 × (100 + 1) = 3434</code>。"
